def check_equal_parens(s1, s2):
    return s1.count('(') == s1.count(')') and s2.count('(') == s2.count(')')

def check_balanced_parens(s1, s2):
    total_open = s1.count('(') + s2.count('(')
    total_close = s1.count(')') + s2.count(')')
    return total_open == total_close

def match_parens(lst):
    s1, s2 = lst
    if not check_valid_chars(s1) or not check_valid_chars(s2):
        return 'No'
    if not check_equal_parens(s1, s2):
        return 'No'
    if not check_balanced_parens(s1, s2):
        return 'No'
    return 'Yes'

